begin;

-- ── Self-contained DDL: create any tables from migrations 010-013 that may not
--    have been applied yet, so this seed works standalone. All idempotent.
create table if not exists public.platform_metric_snapshots (
  id uuid primary key default gen_random_uuid(),
  workspace_id uuid references public.workspaces(id) on delete cascade not null,
  platform text not null,
  captured_at timestamptz not null default now(),
  metrics jsonb not null default '{}'::jsonb);
create index if not exists pms_ws_platform_time_idx on public.platform_metric_snapshots (workspace_id, platform, captured_at desc);
alter table public.platform_metric_snapshots enable row level security;
drop policy if exists "Owner can read metric snapshots" on public.platform_metric_snapshots;
create policy "Owner can read metric snapshots" on public.platform_metric_snapshots for all using (workspace_id in (select id from public.workspaces where owner_id = auth.uid()));
grant all privileges on public.platform_metric_snapshots to anon, authenticated, service_role;

create table if not exists public.member_messages (
  id uuid primary key default gen_random_uuid(),
  workspace_id uuid references public.workspaces(id) on delete cascade not null,
  platform text not null default 'telegram',
  member_ref text not null,
  display_name text,
  day date not null default current_date,
  message_count integer not null default 0,
  updated_at timestamptz default now(),
  unique(workspace_id, platform, member_ref, day));
create index if not exists member_messages_workspace_idx on public.member_messages(workspace_id, day);
alter table public.member_messages enable row level security;
drop policy if exists "Owner can read member_messages" on public.member_messages;
create policy "Owner can read member_messages" on public.member_messages for all using (workspace_id in (select id from public.workspaces where owner_id = auth.uid()));
grant all privileges on public.member_messages to anon, authenticated, service_role;

create table if not exists public.message_activity (
  id uuid primary key default gen_random_uuid(),
  workspace_id uuid references public.workspaces(id) on delete cascade not null,
  platform text not null,
  bucket_start timestamptz not null,
  message_count integer not null default 0,
  updated_at timestamptz default now(),
  unique(workspace_id, platform, bucket_start));
create index if not exists message_activity_ws_bucket_idx on public.message_activity (workspace_id, bucket_start desc);
alter table public.message_activity enable row level security;
drop policy if exists "Owner can read message_activity" on public.message_activity;
create policy "Owner can read message_activity" on public.message_activity for all using (workspace_id in (select id from public.workspaces where owner_id = auth.uid()));
grant all privileges on public.message_activity to anon, authenticated, service_role;

create table if not exists public.discord_member_tenure (
  id uuid primary key default gen_random_uuid(),
  workspace_id uuid references public.workspaces(id) on delete cascade not null,
  member_ref text not null,
  joined_at timestamptz,
  first_seen timestamptz not null default now(),
  last_seen timestamptz not null default now(),
  unique(workspace_id, member_ref));
create index if not exists dmt_ws_joined_idx on public.discord_member_tenure(workspace_id, joined_at);
alter table public.discord_member_tenure enable row level security;
drop policy if exists "Owner can read member tenure" on public.discord_member_tenure;
create policy "Owner can read member tenure" on public.discord_member_tenure for all using (workspace_id in (select id from public.workspaces where owner_id = auth.uid()));
grant all privileges on public.discord_member_tenure to anon, authenticated, service_role;

create table if not exists public.discord_membership_snapshots (
  id uuid primary key default gen_random_uuid(),
  workspace_id uuid references public.workspaces(id) on delete cascade not null,
  captured_at timestamptz not null default now(),
  total_members integer not null default 0,
  new_members integer not null default 0,
  left_members integer not null default 0);
create index if not exists dms_ws_time_idx on public.discord_membership_snapshots(workspace_id, captured_at desc);
alter table public.discord_membership_snapshots enable row level security;
drop policy if exists "Owner can read membership snapshots" on public.discord_membership_snapshots;
create policy "Owner can read membership snapshots" on public.discord_membership_snapshots for all using (workspace_id in (select id from public.workspaces where owner_id = auth.uid()));
grant all privileges on public.discord_membership_snapshots to anon, authenticated, service_role;

-- Ensure the owner profile row exists (FK target for workspaces).
select id, email, coalesce(raw_user_meta_data->>'full_name', 'Luca Cinicolo')
from auth.users where lower(email) = 'cinicololuca@gmail.com'
on conflict (id) do nothing;

-- Clean prior demo (cascade wipes all child rows) then recreate.
delete from public.workspaces where id = '11111111-1111-4111-8111-111111111111';
values ('11111111-1111-4111-8111-111111111111', (select id from auth.users where lower(email) = 'cinicololuca@gmail.com'), 'Aurelia Protocol (Demo)', 'DeFi Protocol', '10k-50k',
